{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "Each sequence's frames as a track, in frame order.",
  "layer": [
    {
      "mark": {
        "type": "line",
        "strokeWidth": 2
      },
      "encoding": {
        "longitude": {
          "field": "lon",
          "type": "quantitative"
        },
        "latitude": {
          "field": "lat",
          "type": "quantitative"
        },
        "detail": {
          "field": "sequence",
          "type": "nominal"
        },
        "order": {
          "field": "frame",
          "type": "quantitative"
        },
        "color": {
          "field": "sequence",
          "type": "nominal",
          "title": "Sequence"
        }
      }
    },
    {
      "mark": {
        "type": "circle",
        "size": 40
      },
      "encoding": {
        "longitude": {
          "field": "lon",
          "type": "quantitative"
        },
        "latitude": {
          "field": "lat",
          "type": "quantitative"
        },
        "color": {
          "field": "sequence",
          "type": "nominal"
        },
        "tooltip": [
          {
            "field": "sequence",
            "type": "nominal"
          },
          {
            "field": "frame",
            "type": "quantitative"
          },
          {
            "field": "t_s",
            "type": "quantitative",
            "title": "seconds"
          }
        ]
      }
    }
  ]
}
